const item = $input.first().json;
let text = item.content?.[0]?.text || item.text || JSON.stringify(item);
text = text.trim();
if (text.startsWith('```')) {
  text = text.replace(/^```(?:json)?\n?/, '').replace(/\n?```$/, '');
}

let parsed;
try { parsed = JSON.parse(text); }
catch (e) {
  return [{ json: { ok: false, rejection_reason: 'invalid_json', raw: text.slice(0,2000), error: String(e) }}];
}

const validConf = new Set(['low','medium','high']);
const clusters = Array.isArray(parsed.clusters) ? parsed.clusters : [];
const rows = [];
for (const c of clusters) {
  if (!c || !c.agent_id || !c.proposed_brief_edit) continue;
  rows.push({
    agent_id: c.agent_id,
    correction_type: 'pattern_recall',
    detection_source: 'vera_feedback_aggregation',
    pattern_reason_code: c.reason_code || null,
    consumed_feedback_ids: Array.isArray(c.feedback_ids) ? c.feedback_ids : [],
    correction_instruction: String(c.correction_instruction || '').slice(0, 2000),
    proposed_brief_edit: String(c.proposed_brief_edit || '').slice(0, 4000),
    confidence: validConf.has(c.confidence) ? c.confidence : 'low',
    approval_state: 'proposed',
    status: 'open',
    detected_at: new Date().toISOString(),
  });
}
return rows.map(r => ({ json: r }));

// For each correction just written (Supabase returns inserted rows), mark the
// feedback rows it consumed. We fan out PATCH requests per feedback id.
const inserted = $input.first().json;
const rows = Array.isArray(inserted) ? inserted : [inserted];
const out = [];
for (const r of rows) {
  if (!r || !r.id || !Array.isArray(r.consumed_feedback_ids)) continue;
  for (const fid of r.consumed_feedback_ids) {
    out.push({ json: { correction_id: r.id, feedback_id: fid }});
  }
}
return out;
